protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // Preserve EF Core 8 discriminator property name ("Discriminator" instead of "$type")
    // so existing Cosmos DB documents and raw SQL queries remain compatible.
    modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

    // Preserve EF Core 8 compound id format ("Blog|1") so existing documents
    // remain accessible via FindAsync and point-reads.
    modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

    // HasIndex removed — Cosmos DB provider now throws at startup.
    // Manage indexing via the container's indexing policy (Azure Portal / Bicep).
}

